// GraphicsRunningProcesses gets information about processes with a graphics context on a device.
//
// For Kepler or newer fully supported devices.
// This function returns information only about graphics based processes (eg. applications using OpenGL, DirectX)
// To query the current number of running graphics processes, call this function with *infoCount = 0. The return code will be [ErrInsufficientSize], or [Success] if none are running. For this call infos is allowed to be NULL.
// The usedGpuMemory field returned is all of the memory used by the application.
// Keep in mind that information returned by this call is dynamic and the number of elements might change in time. Allocate more space for infos table in case new graphics processes are spawned.
//
// Note: In MIG mode, if device handle is provided, the API returns aggregate information, only if the caller has appropriate privileges. Per-instance information can be queried by using specific MIG device handles. Querying per-instance information using MIG device handles is not supported if the device is in vGPU Host virtualization mode.
//
// See also: [SystemGetProcessName]
//
//   - infoCount: Reference in which to provide the infos array size, and to return the number of returned elements
//   - infos: Reference in which to return the process information
//
// A nil error means infoCount and infos have been populated.
//
// Errors:
//   - [ErrGpuIsLost]: if the target GPU has fallen off the bus or is otherwise inaccessible
//   - [ErrInsufficientSize]: if infoCount indicates that the infos array is too small infoCount will contain minimal amount of space necessary for the call to complete
//   - [ErrInvalidArgument]: if device is invalid, either of infoCount or infos is NULL
//   - [ErrNotSupported]: if this query is not supported by device
//   - [ErrNoPermission]: if the user doesn’t have permission to perform this operation
//   - [ErrUninitialized]: if the library has not been successfully initialized
//   - [ErrUnknown]: on any unexpected error
//
// Wraps [nvmlDeviceGetGraphicsRunningProcesses], bound as nvmlDeviceGetGraphicsRunningProcesses_v3.
//
// The returned slice reuses buf's storage when it has sufficient capacity; pass nil to let the call allocate.
//
// [nvmlDeviceGetGraphicsRunningProcesses]: https://docs.nvidia.com/deploy/nvml-api/latest/api/group__nvmlDeviceQueries.html#_CPPv440nvmlDeviceGetGraphicsRunningProcesses_v312nvmlDevice_tPjP17nvmlProcessInfo_t
func (d Device) GraphicsRunningProcesses(buf []ProcessInfo) ([]ProcessInfo, error) {
	count := uint32(cap(buf))
	buf = buf[:cap(buf)]
	var p *ProcessInfo
	if count > 0 {
		p = &buf[0]
	}
	for {
		n := count
		err := deviceGetGraphicsRunningProcesses(d, &n, p)
		if err == nil && n <= count {
			return buf[:n], nil
		}
		if err != nil && !errors.Is(err, ErrInsufficientSize) {
			return nil, err
		}
		count = n + n/2 + 4
		buf = make([]ProcessInfo, count)
		p = &buf[0]
	}
}

